<script setup lang="ts">
import {nextQuestion} from '../learningFlow';
import {ref,computed,watch} from 'vue';import TraceView from '../components/TraceView.vue';import SchedulePlayback from '../components/SchedulePlayback.vue';import {api,type Trace,type Simulation,type Question,type Grade,type Execution,type Schema,type Table} from '../api';import {useLab} from '../store';import SqlEditor from '../components/SqlEditor.vue';import ResultTable from '../components/ResultTable.vue';import StructuredAnswer from '../components/StructuredAnswer.vue';import PredictionCheckpoint from '../components/PredictionCheckpoint.vue';
const preview=ref<Table>();async function previewTable(name:string){const q=question.value;if(!q)return;const r=await lab.run<Table>('trial','fixture_preview',{fixture:q.fixture,relation:name});if(r)preview.value=r;}
const showPrediction=ref(true);const predictionIds:Record<string,string>={projection:'distinct',where:'where-truth',null:'null-test',count:'count-null',aggregate:'having',join:'outer-join',left:'on-where'};
const editor=ref<InstanceType<typeof SqlEditor>>();
const props=defineProps<{theme:string}>();const lab=useLab();const selected=ref(lab.selectedQuestion||lab.workspace?.learning.last_question||'relation');const hint=ref(0);const viewed=ref(false);watch(()=>lab.selectedQuestion,id=>{if(id)selected.value=id});const solution=ref(false);const onlyMistakes=ref(false);const grading=ref<Grade>();const trial=ref<Execution>();const process=ref<{kind:string,trace?:Trace,simulation?:Simulation,source?:string}>();const fixtureSchema=ref<Schema>(lab.schema);const question=computed(()=>lab.questions.find(q=>q.id===selected.value));const key=computed(()=>`${selected.value}@${lab.workspace?.exercise_seed??0}`);const answer=computed({get:()=>lab.workspace?.exercise_answers[key.value]??question.value?.starter??'',set:(v:string)=>{lab.workspace!.exercise_answers[key.value]=v;lab.workspace!.learning.last_question=selected.value;lab.touch();grading.value=undefined;trial.value=undefined;process.value=undefined;}});const chapters=computed(()=>[...new Set(lab.questions.map(q=>q.chapter))]);
watch(selected,id=>{lab.selectedQuestion=id});
const next=computed(()=>nextQuestion(lab.questions,lab.workspace?.progress??{},lab.workspace?.exercise_seed??0,selected.value));
watch(()=>lab.epoch,()=>{process.value=undefined});
watch(question,async q=>{showPrediction.value=true;preview.value=undefined;lab.invalidateJobs(['grade','trial','exercise-trace']);hint.value=lab.workspace?.learning.attempts[key.value]?.hints_used??0;viewed.value=lab.workspace?.learning.attempts[key.value]?.solution_viewed??false;solution.value=false;grading.value=undefined;trial.value=undefined;process.value=undefined;if(q){try{const schema=await api<Schema>('fixture_schema',{fixture:q.fixture});if(q===question.value)fixtureSchema.value=schema}catch(e){lab.fail(e)}}},{immediate:true});
function recordHelp(){lab.workspace!.learning.last_question=selected.value;const state=lab.workspace!.learning.attempts;const old=state[key.value];state[key.value]={attempts:old?.attempts??0,hints_used:hint.value,solution_viewed:viewed.value,assisted:true,status:old?.status??'unattempted'};lab.markDirty();}
function nextHint(){if(hint.value<3){hint.value++;recordHelp();}}
function toggleSolution(){solution.value=!solution.value;if(solution.value&&!viewed.value){viewed.value=true;recordHelp();}}
async function grade(){if(!question.value)return;const r=await lab.run<Grade>('grade','grade',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed,engine:question.value.engine});if(r){grading.value=r;lab.workspace!.progress[key.value]=r.status;const previous=lab.workspace!.learning.attempts[key.value];lab.workspace!.learning.attempts[key.value]={attempts:(previous?.attempts??0)+1,hints_used:hint.value,solution_viewed:viewed.value,assisted:hint.value>0||viewed.value,status:r.status};lab.workspace!.learning.last_question=selected.value;if(r.status==='failed'&&!lab.workspace!.mistakes.includes(key.value)){lab.workspace!.mistakes.push(key.value);lab.workspace!.mistakes=lab.workspace!.mistakes.slice(-500);}lab.markDirty();lab.log(r.message)}}
async function visualize(){process.value=undefined;if(!question.value)return;await editor.value?.source(true);const r=await lab.run<{kind:string,trace?:Trace,simulation?:Simulation,source?:string}>('exercise-trace','exercise_trace',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed});if(r)process.value=r;}
async function run(){if(!question.value)return;if(question.value.engine==='mysql'){lab.log('MySQL 例程需用提交命令在隔离沙箱验证；运行快捷键不会提交。');return;}if(['algebra','schedule'].includes(question.value.kind)){await visualize();return;}if(question.value.kind==='concept'){lab.log('当前结构化答案已预览；使用提交按钮进行判题。');return;}const r=await lab.run<Execution>('trial','exercise_run',{id:question.value.id,answer:answer.value,seed:lab.workspace!.exercise_seed,engine:question.value.engine});if(r)trial.value=r;}
async function reseed(){lab.touch();lab.questions=await api<Question[]>('catalog',{seed:lab.workspace!.exercise_seed});grading.value=undefined;}
function reset(){delete lab.workspace!.exercise_answers[key.value];delete lab.workspace!.progress[key.value];grading.value=undefined;trial.value=undefined;process.value=undefined;lab.touch();}
const differences=computed(()=>grading.value?.diff??{expected:[],actual:[]});

const visible=(q:Question)=>!onlyMistakes.value||lab.workspace!.mistakes.some(k=>k.startsWith(`${q.id}@`));
</script>
<template><div class="exercise-page"><aside class="course-tree"><div class="sidebar-title">HNU DATABASE COURSE</div><label class="check"><input v-model="onlyMistakes" type="checkbox">只看错题</label><details v-for="chapter in chapters" :key="chapter" open><summary>{{String(chapter).padStart(2,'0')}} {{lab.questions.find(q=>q.chapter===chapter)?.chapter_title}}</summary><button v-for="q in lab.questions.filter(q=>q.chapter===chapter&&visible(q))" :key="q.id" :class="{active:selected===q.id}" @click="selected=q.id"><span :class="lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]==='passed'?'success':'muted'">{{lab.workspace?.progress[`${q.id}@${lab.workspace.exercise_seed}`]==='passed'?'✓':'○'}}</span>{{q.title}}</button></details></aside><section v-if="question" class="exercise-work"><header class="page-heading"><div><span class="eyebrow">CHALLENGE {{question.chapter}} · {{question.engine.toUpperCase()}}</span><h1>{{question.title}}</h1></div></header><p v-if="lab.workspace?.learning.mode!=='free'" class="lesson-goal">本节目标：{{question.knowledge}}</p><PredictionCheckpoint v-if="showPrediction&&lab.workspace?.learning.mode!=='free'&&predictionIds[question.id]" :id="predictionIds[question.id]!" @skip="showPrediction=false"/><p class="question-prompt">{{question.prompt}}</p><details class="exercise-settings"><summary>实验设置与教学依据</summary><div class="seed"><label>随机种子<input v-model.number="lab.workspace!.exercise_seed" type="number" min="0" max="4294967295" @change="reseed"></label></div><div class="source-note">依据：{{question.source}} · {{question.pages}}<br>公开数据：{{question.fixture}}；运行与判题使用隔离数据库，不改变你的工作区。</div></details><div class="toolbar"><span>公开表预览（前 100 行）</span><button v-for="r in fixtureSchema.relations" :key="r.name" @click="previewTable(r.name)">{{r.name}}</button></div><ResultTable v-if="preview" :table="preview" title="公开数据预览" compact/><div class="exercise-actions"><button class="primary" data-testid="grade" :disabled="!!lab.jobs.grade" @click="grade">✓ 提交判题</button><button v-if="['query','mutation','schema','routine'].includes(question.kind)" :disabled="!!lab.jobs.trial" @click="run">▶ 试运行</button><button v-if="['query','algebra','schedule'].includes(question.kind)" data-testid="exercise-trace" @click="visualize">逐步演示</button><button @click="nextHint">{{hint>=3?'已显示全部提示':'下一层提示'}}</button><button @click="toggleSolution">{{solution?'收起解析':'查看解析'}}</button><button @click="reset">重新作答</button></div><div v-for="(text,i) in question.hints.slice(0,hint)" :key="i" class="notice"><strong>{{['观察提示','知识提示','结构提示'][i]}}</strong> {{text}}</div><StructuredAnswer v-if="question.answer_ui==='structured'" v-model="answer" :solution="question.solution"/><div v-if="question.answer_ui!=='structured'" class="answer-editor"><SqlEditor ref="editor" :id="`exercise-${key}`" v-model="answer" :schema="fixtureSchema" :engine="question.engine" :language="['concept','schedule'].includes(question.kind)?'json':question.kind==='algebra'?'plaintext':'sql'" :theme="props.theme" @run="run" @submit="grade"/></div><TraceView v-if="process?.trace" :trace="process.trace" @highlight="editor?.highlight($event)"/><SchedulePlayback v-if="process?.simulation" :result="process.simulation" :source="process.source??''"/><div v-if="grading" class="grade-card" :class="grading.status"><strong>{{grading.status==='passed'?'✓ 测试通过':grading.status==='failed'?'需要再试一次':'判定未完成'}}</strong><p>{{grading.message}}</p><p v-if="grading.status==='passed'">{{lab.workspace?.learning.attempts[key]?.assisted?'辅助通过 · 建议稍后独立复习':'独立通过'}}</p><small>{{grading.explanation}}</small><button v-if="grading.status==='passed'&&next" class="primary" data-testid="next-lesson" @click="lab.study(next.id)">继续下一节：{{next.title}} →</button><button v-else-if="grading.status==='passed'" @click="lab.page='learn'">查看学习总结</button><ResultTable v-if="grading.expected" :table="grading.expected" :diff-rows="differences.expected" title="失败数据组的期望结果" compact/><ResultTable v-if="grading.actual" :table="grading.actual" :diff-rows="differences.actual" title="你的结果" compact/></div><div v-if="trial"><div v-if="trial.error" class="notice warning">{{trial.error}}</div><ResultTable v-for="(r,i) in trial.results" :key="i" :table="r.table" :title="`试运行 ${i+1} · ${r.affected} 行受影响`"/></div><section v-if="solution" class="solution"><h3>参考答案与解析</h3><pre>{{question.solution}}</pre><p>{{question.explanation}}</p><button @click="answer=question.solution">填入参考答案</button></section></section></div></template>
